sql.where:
and o.order_id=#{orderId}
and o.order_no like concat('%',#{orderNo},'%')
and o.user_id=#{userId}
and o.service_id=#{serviceId}
and o.service_name like concat('%',#{serviceName},'%')
and (o.user_info like concat('%',#{userInfo},'%') or exists (select 1 from sys_user su where su.user_id=o.user_id and (su.nick_name like concat('%',#{userInfo},'%') or su.user_name like concat('%',#{userInfo},'%'))))
and o.phone like concat('%',#{phone},'%')
and o.master_id=#{masterId}
and o.order_status=#{orderStatus}
and o.payment_status=#{paymentStatus}
and o.create_time >= #{params.beginTime}
and o.create_time < date_add(#{params.endTime},interval 1 day)

${params.dataScope}

mapper.select:
select ,coalesce(nullif(u.nick_name,''),nullif(o.user_info,''),'-') admin_user_info from zjudg_order o
left join sys_user u on u.user_id=o.user_id
where o.order_id=#{id}

select  from zjudg_order o
where o.user_id=#{userId}
and o.order_status=#{orderStatus}
order by o.create_time desc

select count(1) from zjudg_order o
where o.user_id=#{userId}
and o.order_status=#{orderStatus}

select  from zjudg_order o
    where o.master_id is null and o.order_status='0' and o.payment_status='1' and o.appointment_date >= #{appointmentDate}
    and o.slot_id=#{slotId}
    order by o.appointment_date asc, o.create_time asc

select  from zjudg_order o
left join zjudg_service s on s.service_id = o.service_id
where o.master_id is null and o.order_status='0' and o.payment_status='1' and o.appointment_date >= #{appointmentDate}
and o.slot_id=#{slotId}
and (
  s.category_id in
  #{skill}

    or s.category_id like concat(#{skill}, '_%')

)
order by o.appointment_date asc, o.create_time asc
